package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.history.AsOfGuard;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /**
     * What the screen is told about a grade's rate; the percent with two decimals, and the date it
     * applies from (null: from the beginning of time) and through (null: no end).
     */
    public record RateView(String grade, String pct, LocalDate from, LocalDate to) {

        public static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getPct().toPlainString(), rate.getFromDate(),
                    rate.getToDate());
        }
    }

    /**
     * A rate as entered on the form: a percent of 0.00 or more with up to two decimals, and the date
     * it applies from (none: from the beginning of time) and through (none: no end).
     */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct, LocalDate from,
            LocalDate to) {
    }

    private final RateService service;
    private final SheetHistory history;

    public RateController(RateService service, SheetHistory history) {
        this.service = service;
        this.history = history;
    }

    /**
     * The sheet's rates by grade, each grade's by from-date; a grade with no rate is not listed. With an
     * as-of date, as they stood at the end of it.
     */
    @GetMapping
    public List<RateView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf) {
        return history.views(sheetId, AsOfGuard.date(asOf)).map(SheetHistory.Views::rates)
                .orElseGet(() -> service.list(sheetId).stream().map(RateView::of).toList());
    }

    /**
     * The rates of the sheet's ancestors, nearest first (its parent's, then its parent's parent's, up to
     * three levels up), each sheet's by grade and from-date: what a grade with no rate in force on the
     * sheet falls back to. With an as-of date, each as it stood at the end of it.
     */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) String asOf) {
        return history.inherited(sheetId, AsOfGuard.date(asOf)).stream()
                .map(rates -> rates.stream().map(RateView::of).toList()).toList();
    }

    /**
     * Set the rate for a grade from a date (through a to-date, if given), replacing any it had from
     * that date; a to-date before the from-date is refused.
     */
    @PutMapping("/{grade}")
    public RateView set(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid RateForm form) {
        return RateView.of(service.set(sheetId, SignedIn.name(user), grade, form.from(),
                form.to(), new BigDecimal(form.pct())));
    }

    /** What the screen is told of a rate preview: the claims whose due would change, and the sum of the differences. */
    public record PreviewView(int count, String diff) {
    }

    /**
     * How many OPEN and PENDING claims on a grade would show a different due were a candidate rate
     * applied to the grade on every date, and the sum of the differences; nothing is saved.
     */
    @GetMapping("/{grade}/preview")
    public PreviewView preview(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String pct) {
        RateService.Preview preview = service.preview(sheetId, grade, new BigDecimal(pct));
        return new PreviewView(preview.count(), preview.diff().toPlainString());
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The rates for the grades on a sheet: listed and set. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollups rollups;
    private final Audit audit;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final Dues dues;

    public RateService(RateRepository rates, SheetService sheets, Rollups rollups, Audit audit, PersonRepository people,
            ClaimRepository claims, Dues dues) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
        this.people = people;
        this.claims = claims;
        this.dues = dues;
    }

    /**
     * What a candidate rate for a grade would change: how many OPEN and PENDING claims of people on
     * the grade (the grade in force on the claim's date) would show a different due, and the sum of
     * the differences (new due minus current due).
     */
    public record Preview(int count, BigDecimal diff) {
    }

    /**
     * Preview a candidate rate applied to a grade on every date, in place of the grade's rates;
     * nothing is saved and nothing is audited. A claim bound by a statement keeps its figure, and a
     * settled claim is not counted.
     */
    @Transactional(readOnly = true)
    public Preview preview(String sheetId, String grade, BigDecimal pct) {
        Dues.Basis current = dues.live(sheetId);
        List<Rate> candidate = new ArrayList<>(current.rates().stream()
                .filter(rate -> !rate.getGrade().equals(grade)).toList());
        candidate.add(new Rate(sheetId, grade, null, pct.setScale(2, RoundingMode.UNNECESSARY)));
        Dues.Basis previewed = new Dues.Basis(current.sheet(), candidate, current.inherited(), current.corrected());
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        int count = 0;
        BigDecimal diff = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !claim.getStatus().isOpen() || claim.getSettledDue() != null
                    || !grade.equals(person.gradeOn(claim.getDate()))) {
                continue;
            }
            BigDecimal was = dues.due(claim, grade, current);
            BigDecimal now = dues.due(claim, grade, previewed);
            if (was == null ? now == null : now != null && was.compareTo(now) == 0) {
                continue;
            }
            count++;
            diff = diff.add(orZero(now)).subtract(orZero(was));
        }
        return new Preview(count, diff.setScale(2, RoundingMode.UNNECESSARY));
    }

    private static BigDecimal orZero(BigDecimal value) {
        return value == null ? BigDecimal.ZERO : value;
    }

    /** The sheet's rates by grade. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(sheetId);
    }

    /**
     * Set the rate for a grade from a date (null: from the beginning of time), replacing any the
     * grade had from that same date, applying through a to-date (null: no end); a to-date before the
     * from-date is refused.
     */
    @Transactional
    public synchronized Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to,
            BigDecimal pct) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A rate's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId);
        Rollups.Rollup before = rollups.take(sheetId);
        BigDecimal percent = pct.setScale(2, RoundingMode.UNNECESSARY);
        Rate rate = rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from)
                .orElseGet(() -> new Rate(sheetId, grade, from, percent));
        rate.setPct(percent);
        rate.setToDate(to);
        Rate saved = rates.saveAndFlush(rate);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().toPlainString()
                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : "")
                + (saved.getToDate() != null ? " to=" + saved.getToDate() : ""));
        rollups.audit(sheetId, user, before);
        return saved;
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { ClaimView, LateTerms, cents, isCorrection, lateBoundaries, money } from './claims';
import { valueOn } from './session';
import { Grade } from './people';

export interface RateView {
  grade: Grade;
  /** The percent with two decimals, e.g. "12.50". */
  pct: string;
  /** The date (yyyy-mm-dd) the rate applies from; null when it applies from the beginning of time. */
  from: string | null;
  /** The last date (yyyy-mm-dd) the rate applies on; null when it has no end. */
  to: string | null;
}

/**
 * A rate as set through the form; a null from-date applies from the beginning of time, a null
 * to-date has no end.
 */
export interface RateForm {
  pct: string;
  from: string | null;
  to: string | null;
}

/**
 * What a candidate rate for a grade would change: how many OPEN and PENDING claims would show a
 * different due, and the sum of the differences (new minus current, two decimals).
 */
export interface RatePreview {
  count: number;
  diff: string;
}

/** A from-date as a rate takes it: yyyy-mm-dd. */
export const FROM_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * The rate a grade has in force on a date (yyyy-mm-dd): of its rates with no from-date or one on or
 * before the date, the one with the latest; null when the date is before every rate of the grade, or
 * after that one's to-date. When the sheet has none, its parent's rate for the grade and date, then
 * its parent's parent's, and so on (`inherited`, nearest first).
 */
export function rateOn(rates: RateView[], grade: Grade, date: string, inherited: RateView[][] = []): string | null {
  for (const level of [rates, ...inherited]) {
    const pct = ownRateOn(level, grade, date);
    if (pct !== null) return pct;
  }
  return null;
}

/** The rate a grade has in force on a date among one sheet's rates alone (see rateOn). */
function ownRateOn(rates: RateView[], grade: Grade, date: string): string | null {
  let best: RateView | null = null;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (best === null || (r.from !== null && (best.from === null || r.from > best.from))) best = r;
  }
  if (best === null || (best.to !== null && best.to < date)) return null;
  return best.pct;
}

/** Whether two rates are for the same grade and from-date, so one replaces the other. */
export function sameSlot(a: RateView, b: RateView): boolean {
  return a.grade === b.grade && a.from === b.from;
}

/** A percent as a rate takes it: 0.00 or more, with up to two decimals. */
export const PERCENT = /^\d{1,3}(\.\d{1,2})?$/;

/** Shown in place of a due when the grade has no rate. */
export const NO_RATE = 'n/a';

/**
 * What is due on an amount in whole cents at a rate (a two-decimal percent): the amount times the
 * rate divided by 100, rounded half to even (or half up) to whole cents (a negative amount rounds as
 * its opposite does). Worked in integers so it is exact.
 */
export function dueCents(amountCents: number, pct: string, times = 1, halfUp = false): number {
  if (amountCents < 0) return -dueCents(-amountCents, pct, times, halfUp);
  const [whole, frac = ''] = pct.split('.');
  const basisPoints = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  const exact = BigInt(amountCents) * basisPoints * BigInt(times);
  const quotient = exact / 10000n;
  const remainder = exact % 10000n;
  const up = remainder > 5000n || (remainder === 5000n && (halfUp || quotient % 2n === 1n));
  return Number(up ? quotient + 1n : quotient);
}

/** What is due on an amount in whole cents at a rate, shown with two decimals; n/a with no rate in force. */
export function due(amountCents: number, pct: string | null): string {
  return pct === null ? NO_RATE : money(dueCents(amountCents, pct));
}

/**
 * A claim's due in whole cents: the due fixed when it was settled (frozen as it was settled), or else
 * the greater of the floor (in whole cents) and its figure with the late charge on top. Its figure is
 * the rate figure its person's last statement bound it to (unless it is PENDING), or else its amount
 * at the rate the grade has in force on the claim's date; the late charge is, for every full 30 days
 * the claim is overdue, the late percent in force on that boundary date (its due-by plus 30, 60, 90
 * ... days) of the figure plus the charges of the boundaries before it (compounding), each rounded
 * like the claim, added up. The floor is applied last; the one
 * given is the one in force on the claim's date. Live figures round half up when `halfUp` (see
 * roundsHalfUp), else half to even. The charge and floor are never bound by a statement. A correction
 * has no floor and no late charge. Null when there is no figure.
 */
export function claimDueCents(
  claim: ClaimView,
  rates: RateView[],
  grade: Grade,
  floorCents: number,
  late: LateTerms,
  halfUp = false,
  inherited: RateView[][] = [],
): number | null {
  if (claim.settledDue !== null) return cents(claim.settledDue);
  let figure: number | null;
  if (claim.stated && claim.status !== 'PENDING') {
    figure = claim.statedDue === null ? null : cents(claim.statedDue);
  } else {
    const pct = rateOn(rates, grade, claim.date, inherited);
    figure = pct === null ? null : dueCents(cents(claim.amount), pct, 1, halfUp);
  }
  if (figure === null || isCorrection(claim)) return figure;
  const charge = lateBoundaries(claim, late)
    .reduce((sum, on) => sum + dueCents(figure + sum, valueOn(late.history, on, '0.00'), 1, halfUp), 0);
  return Math.max(figure + charge, floorCents);
}

// The rates for the grades on a sheet, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);

  /** The sheet's rates, each grade's by from-date; a grade with no rate is not listed. */
  list(sheet: string): Promise<RateView[]> {
    return firstValueFrom(this.http.get<RateView[]>(this.url(sheet)));
  }

  /**
   * The rates of the sheet's ancestors, nearest first (its parent's, up to three levels up): what a
   * grade with no rate in force on the sheet falls back to.
   */
  inherited(sheet: string): Promise<RateView[][]> {
    return firstValueFrom(this.http.get<RateView[][]>(`${this.url(sheet)}/inherited`));
  }

  /** Set a grade's rate from a date, replacing any it had from that date. */
  set(sheet: string, grade: Grade, form: RateForm): Promise<RateView> {
    return firstValueFrom(this.http.put<RateView>(`${this.url(sheet)}/${grade}`, form));
  }

  /** Preview a candidate rate applied to a grade on every date; nothing is saved. */
  preview(sheet: string, grade: Grade, pct: string): Promise<RatePreview> {
    return firstValueFrom(
      this.http.get<RatePreview>(`${this.url(sheet)}/${grade}/preview`, { params: { pct } }),
    );
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/rates`;
  }
}
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { GRADES, Grade } from '../../core/people';
import { FROM_DATE, NO_RATE, PERCENT, RatePreview, RateView, RatesApi, rateOn } from '../../core/rates';
import { Session } from '../../core/session';

// The sheet's rates: each grade's rate in force on the sheet's today, every rate by grade and
// from-date, and one form to set a grade's rate from a date (or from the beginning of time) through
// a to-date (or with no end).
@Component({
  selector: 'app-rates',
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form (submit)="save($event)" aria-label="Set a rate">
        <label for="rate-form-grade">Grade</label>
        <select
          id="rate-form-grade"
          data-testid="rate-form-grade"
          [value]="grade()"
          (change)="grade.set(gradeOf($event)); error.set(null)"
        >
          @for (g of grades; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input
          id="rate-form-pct"
          data-testid="rate-form-pct"
          inputmode="decimal"
          [value]="pct()"
          (input)="pct.set(value($event)); error.set(null)"
        />
        <label for="rate-form-from">From (empty: from the start)</label>
        <input
          id="rate-form-from"
          type="date"
          data-testid="rate-form-from"
          [value]="from()"
          (input)="from.set(value($event)); error.set(null)"
        />
        <label for="rate-form-to">To (empty: no end)</label>
        <input
          id="rate-form-to"
          type="date"
          data-testid="rate-form-to"
          [value]="to()"
          (input)="to.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        @if (error(); as message) {
          <p role="alert" data-testid="rate-form-error">{{ message }}</p>
        }
      </form>
      <form (submit)="runPreview($event)" aria-label="Preview a rate">
        <label for="rate-preview-grade">Preview grade</label>
        <select
          id="rate-preview-grade"
          data-testid="rate-preview-grade"
          [value]="previewGrade()"
          (change)="previewGrade.set(gradeOf($event)); clearPreview()"
        >
          @for (g of grades; track g) {
